const inputData = $input.all();
let currentNumber = 1;

if (inputData.length > 0 && inputData[0].json.number) {
  currentNumber = inputData[0].json.number;
}

console.log(`Processing PDF number: ${currentNumber}`);

return [{
  json: {
    number: currentNumber
  }
}];

// تحويل PDF إلى Base64 لـ Google Vision
const binaryData = $binary.data;

if (!binaryData) {
  throw new Error('No binary data found');
}

// تحويل لـ Base64
const base64Content = binaryData.data;

console.log('PDF downloaded, size:', binaryData.data.length);
console.log('File type:', binaryData.mimeType);

return [{
  json: {
    base64Content: base64Content,
    mimeType: binaryData.mimeType,
    fileName: binaryData.fileName || `pdf-${$('Counter Node').first().json.number}.pdf`
  }
}];

const visionResult = $input.first().json;

console.log('Vision API Response:', JSON.stringify(visionResult, null, 2));

// استخراج النص من Google Vision API
let extractedText = '';

if (visionResult.responses && visionResult.responses[0]) {
  const response = visionResult.responses[0];

  // جرب fullTextAnnotation أولاً
  if (response.fullTextAnnotation && response.fullTextAnnotation.text) {
    extractedText = response.fullTextAnnotation.text;
  }
  // إذا لم يعمل، جرب textAnnotations
  else if (response.textAnnotations && response.textAnnotations.length > 0) {
    extractedText = response.textAnnotations[0].description || '';
  }
  // تحقق من وجود أخطاء
  else if (response.error) {
    return {
      json: {
        error: true,
        message: 'Google Vision API Error: ' + response.error.message,
        errorDetails: response.error
      }
    };
  }
  else {
    return {
      json: {
        error: true,
        message: 'No text detected by Google Vision API',
        response: response
      }
    };
  }
} else {
  return {
    json: {
      error: true,
      message: 'Invalid response from Google Vision API',
      fullResponse: visionResult
    }
  };
}

// تنظيف النص
const cleanedText = extractedText
  .replace(/\r\n/g, '\n')
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/\n\s*\n/g, '\n\n')
  .trim();

// تقسيم النص إلى أجزاء
const chunkSize = 4000;
const chunks = [];

for (let i = 0; i < cleanedText.length; i += chunkSize) {
  chunks.push(cleanedText.slice(i, i + chunkSize));
}

console.log('Extracted text length:', extractedText.length);
console.log('Text preview:', extractedText.substring(0, 300));

return {
  json: {
    originalText: extractedText,
    cleanedText: cleanedText,
    textChunks: chunks,
    success: true,
    textLength: extractedText.length
  }
};

let outputStr = $input.first().json.output;

let jsonMatch = outputStr.match(/({[\s\S]*})/);

if (!jsonMatch) {
  throw new Error("No valid JSON found in AI output!");
}

let data = JSON.parse(jsonMatch[1]);

if (!data.jsonnumber) {
  data.jsonnumber = $('Counter Node').first().json.number;
}

console.log(`Final data for PDF ${data.jsonnumber}:`, JSON.stringify(data, null, 2));

return [{ json: data }];

let current = $('Counter Node').first().json.number;

console.log(`Finished processing PDF number: ${current}`);

if (current >= 50) {
  console.log('All PDFs processed!');
  return [{
    json: {
      finished: true,
      message: `Completed processing PDFs 1-${current}`,
      totalProcessed: current
    }
  }];
}

let next = current + 1;
console.log(`Next PDF to process: ${next}`);

return [{
  json: {
    number: next,
    continue: true,
    currentlyProcessed: current
  }
}];

let nextNumber = $('Loop Check').first().json.number;

console.log(`Looping back with number: ${nextNumber}`);

return [{
  json: {
    number: nextNumber
  }
}];
